export interface DocumentLinkOptions {
  mode?: "cloud" | "demo"
  companyId?: string
  origin?: string
  purpose?: "download" | "preview"
  /** Only for JSON/XML just generated by the trusted evidence resolver. */
  generated?: boolean
}

const cleanReference = (value: unknown): value is string =>
  typeof value === "string" && Boolean(value) && value === value.trim() && !/[\u0000-\u0020\u007f\\]/.test(value)

/** A document reference is an exact private object, never an arbitrary URL. */
export function getPrivateDocumentReference(value: unknown, companyId: string, origin?: string) {
  if (!cleanReference(value) || !companyId || value.startsWith("//")) return null
  try {
    const base = new URL(origin || "https://pld.invalid").origin
    if (!value.startsWith("/") && !origin) return null
    const url = new URL(value, base)
    if (url.origin !== base || url.search || url.hash || url.username || url.password) return null
    const match = /^\/api\/v1\/companies\/([^/]+)\/files\/([^/]+)$/.exec(url.pathname)
    if (!match) return null
    const scope = decodeURIComponent(match[1]), versionId = decodeURIComponent(match[2])
    if (scope !== companyId || !/^[A-Za-z0-9][A-Za-z0-9._-]{0,179}$/.test(versionId)) return null
    // Reject encoded separators/ambiguous double encodings in scope components.
    if (/[/?#%\\\u0000-\u0020\u007f]/.test(scope)) return null
    return { companyId: scope, versionId, href: `/api/v1/companies/${encodeURIComponent(scope)}/files/${encodeURIComponent(versionId)}` }
  } catch { return null }
}

export function resolveSafeDocumentHref(value: unknown, options: DocumentLinkOptions = {}): string | null {
  if (typeof value !== "string") return null
  const privateFile = options.companyId ? getPrivateDocumentReference(value, options.companyId, options.origin) : null
  if (privateFile) return privateFile.href
  if (options.generated && options.purpose !== "preview" && /^data:application\/(?:json|xml);charset=utf-8,[^\s]*$/i.test(value)) return value
  if (options.mode !== "demo") return null
  if (/^data:(?:application\/(?:pdf|json|xml|vnd\.[a-z0-9.+-]+)|text\/(?:plain|csv|xml)|image\/(?:png|jpeg|webp))(?:;charset=[a-z0-9-]+)?(?:;base64)?,/i.test(value)) return value
  if (cleanReference(value) && value.startsWith("blob:") && options.origin) {
    try { if (new URL(value).origin === new URL(options.origin).origin) return value } catch { /* blocked */ }
  }
  return null
}
